import React, { useEffect, useState, useMemo } from "react";
import { fetchUsers } from "../api/userServices";
import { deriveStatus } from "../../shared/types";

// ── colour tokens ─────────────────────────────────────────────
const ORANGE = "#EA580C";
const NAVY = "#0F172A";
const SLATE = "#64748B";
const BORDER = "#E2E8F0";
const SKY = "#0EA5E9";

// ── types ──────────────────────────────────────────────────────
type GrowthPeriod = "days" | "weeks" | "months";

interface AppUser {
  id: string;
  name: string;
  email?: string | null;
  phone?: string | null;
  image_url?: string | null;

  created_at?: string | null;
  updated_at?: string | null;
  last_active?: string | null;

  user_type_names?: string[];
  location?: string;
  location_names?: string[];
  skills_id?: string[];

  is_active?: boolean | null;
  status?: "active" | "pending" | "suspended" | "dormant";
}

interface GrowthBucket {
  label: string;
  clients: number;
  freelancers: number;
}

// ── helpers ────────────────────────────────────────────────────
function startOfDay(d: Date) {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

function isoWeek(d: Date): string {
  const tmp = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  tmp.setUTCDate(tmp.getUTCDate() + 4 - (tmp.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(tmp.getUTCFullYear(), 0, 1));
  const wk = Math.ceil(((tmp.getTime() - yearStart.getTime()) / 86400000 + 1) / 7);
  return `W${wk}`;
}

// ── growth builder ─────────────────────────────────────────────
function buildGrowthBuckets(users: AppUser[], period: GrowthPeriod): GrowthBucket[] {
  const now = new Date();

  const base = users;

  if (period === "days") {
    const buckets: any[] = Array.from({ length: 14 }, (_, i) => {
      const d = new Date(now);
      d.setDate(d.getDate() - (13 - i));
      return {
        label: d.toLocaleDateString("en-US", { weekday: "short", day: "numeric" }),
        clients: 0,
        freelancers: 0,
        _key: startOfDay(d).getTime(),
      };
    });

    base.forEach((u) => {
      if (!u.created_at) return;

      const key = startOfDay(new Date(u.created_at)).getTime();
      const bucket = buckets.find((b) => b._key === key);

      if (!bucket) return;

      const types = u.user_type_names ?? [];
      if (types.includes("hire talent")) bucket.clients++;
      if (types.includes("find work")) bucket.freelancers++;
    });

    return buckets;
  }

  if (period === "weeks") {
    const map = new Map<string, GrowthBucket>();

    for (let i = 7; i >= 0; i--) {
      const d = new Date(now);
      d.setDate(d.getDate() - i * 7);
      const label = isoWeek(d);
      map.set(label, { label, clients: 0, freelancers: 0 });
    }

    base.forEach((u) => {
      if (!u.created_at) return;

      const label = isoWeek(new Date(u.created_at));
      const bucket = map.get(label);

      if (!bucket) return;

      const types = u.user_type_names ?? [];
      if (types.includes("hire talent")) bucket.clients++;
      if (types.includes("find work")) bucket.freelancers++;
    });

    return Array.from(map.values());
  }

  const buckets: any[] = Array.from({ length: 6 }, (_, i) => {
    const d = new Date(now.getFullYear(), now.getMonth() - (5 - i), 1);
    return {
      label: d.toLocaleString("default", { month: "short" }),
      clients: 0,
      freelancers: 0,
      _key: `${d.getFullYear()}-${d.getMonth()}`,
    };
  });

  base.forEach((u) => {
    if (!u.created_at) return;

    const d = new Date(u.created_at);
    const key = `${d.getFullYear()}-${d.getMonth()}`;

    const bucket = buckets.find((b) => b._key === key);
    if (!bucket) return;

    const types = u.user_type_names ?? [];
    if (types.includes("hire talent")) bucket.clients++;
    if (types.includes("find work")) bucket.freelancers++;
  });

  return buckets;
}

// ── animated number ────────────────────────────────────────────
function AnimatedNumber({ value }: { value: number }) {
  const [display, setDisplay] = useState(0);

  useEffect(() => {
    let cur = 0;
    const step = Math.ceil(value / 40) || 1;

    const t = setInterval(() => {
      cur += step;
      if (cur >= value) {
        setDisplay(value);
        clearInterval(t);
      } else {
        setDisplay(cur);
      }
    }, 20);

    return () => clearInterval(t);
  }, [value]);

  return <>{display.toLocaleString()}</>;
}

// ── main component ─────────────────────────────────────────────
const UserAnalytics: React.FC = () => {
  const [users, setUsers] = useState<AppUser[]>([]);
  const [loading, setLoading] = useState(true);
  // const [period, setPeriod] = useState<GrowthPeriod>("months");

  // ── initial load
  useEffect(() => {
    fetchUsers()
      .then(setUsers)
      .finally(() => setLoading(false));
  }, []);

  // ── REAL-TIME (simple polling version - upgradeable to Supabase later)
  useEffect(() => {
    const interval = setInterval(async () => {
      try {
        const fresh = await fetchUsers();
        setUsers(fresh);
      } catch {}
    }, 15000); // refresh every 15s

    return () => clearInterval(interval);
  }, []);

  // ── stats
  const stats = useMemo(() => {
    let clients = 0,
      freelancers = 0,
      suspended = 0;

    const locationCount: Record<string, number> = {};
    const skillCount: Record<string, number> = {};

    users.forEach((u) => {
      const types = u.user_type_names ?? [];
      const isClient = types.includes("hire talent");
      const isFreelancer = types.includes("find work");

      const status = deriveStatus(u as any);

      if (status === "suspended") suspended++;
      else {
        if (isClient) clients++;
        if (isFreelancer) freelancers++;
      }

      (u.location_names ?? [u.location].filter(Boolean)).forEach((loc) => {
        if (loc) locationCount[loc] = (locationCount[loc] || 0) + 1;
      });

      // ✅ FIXED TYPE ERROR HERE
      (u.skills_id ?? []).forEach((skill: string) => {
        if (skill) skillCount[skill] = (skillCount[skill] || 0) + 1;
      });
    });

    return {
      total: users.length,
      clients,
      freelancers,
      suspended,
      topLocations: Object.entries(locationCount)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 5)
        .map(([name, count]) => ({ name, count })),

      topSkills: Object.entries(skillCount)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 5)
        .map(([name, count]) => ({ name, count })),
    };
  }, [users]);

  const growthData = useMemo(
    () => buildGrowthBuckets(users, period),
    [users, period]
  );

  // ── loading
  if (loading) {
    return <div style={{ padding: 40, color: SLATE }}>Loading...</div>;
  }

  return (
    <div style={{ fontFamily: "DM Sans" }}>
      <h2 style={{ fontWeight: 800 }}>User Analytics</h2>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 12 }}>
        <div>Total: {stats.total}</div>
        <div>Clients: {stats.clients}</div>
        <div>Freelancers: {stats.freelancers}</div>
        <div>Suspended: {stats.suspended}</div>
      </div>

      {/* FIXED: now properly used */}
      <div style={{ marginTop: 20 }}>
        <h3>Growth</h3>
        <pre>{JSON.stringify(growthData, null, 2)}</pre>
      </div>
    </div>
  );
};

export default UserAnalytics;
